import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { butter, sosfilt, sosGain, type FilterBand } from '../src/dsp/butterworth';
import { fft } from '../src/dsp/fft';
import { averagedSpectrum, spectrogram } from '../src/dsp/spectrum';
import { encodeWav, parseWav } from '../src/dsp/wav';
import { generate } from '../src/dsp/generate';

// Generated by tests/fixtures/make_fixtures.py (NumPy/SciPy).
const ref = JSON.parse(readFileSync(new URL('./fixtures/scipy-reference.json', import.meta.url), 'utf8'));

const maxAbsDiff = (a: ArrayLike<number>, b: ArrayLike<number>) => {
  let max = 0;
  for (let i = 0; i < a.length; i++) max = Math.max(max, Math.abs(a[i] - b[i]));
  return max;
};

describe('fft', () => {
  it('matches numpy.fft.fft', () => {
    const re = Float64Array.from(ref.fft.re);
    const im = Float64Array.from(ref.fft.im);
    fft(re, im);
    expect(maxAbsDiff(re, ref.fft.outRe)).toBeLessThan(1e-9);
    expect(maxAbsDiff(im, ref.fft.outIm)).toBeLessThan(1e-9);
  });

  it('rejects non power-of-two sizes', () => {
    expect(() => fft(new Float64Array(6), new Float64Array(6))).toThrow();
  });
});

describe('butterworth', () => {
  const x = Float32Array.from(ref.x);

  for (const c of ref.filters) {
    const label = `${c.band} order ${c.order} @ ${JSON.stringify(c.cutoff)} Hz`;
    const sos = butter(c.order, c.cutoff, c.band as FilterBand, c.fs);

    it(`${label}: frequency response matches scipy`, () => {
      c.freqs.forEach((f: number, i: number) => {
        expect(sosGain(sos, f, c.fs)).toBeCloseTo(c.gains[i], 6);
      });
    });

    it(`${label}: filtered output matches scipy.signal.sosfilt`, () => {
      // Float32 output, so compare at single-precision tolerance.
      expect(maxAbsDiff(sosfilt(sos, x), c.y)).toBeLessThan(1e-5);
    });
  }

  it('has -3 dB gain at the cutoff', () => {
    const sos = butter(5, 1000, 'lowpass', 44100);
    expect(20 * Math.log10(sosGain(sos, 1000, 44100))).toBeCloseTo(-3.0103, 3);
  });

  it('rejects cutoffs at or above Nyquist', () => {
    expect(() => butter(4, 4000, 'lowpass', 8000)).toThrow(/Nyquist/);
    expect(() => butter(4, [2000, 1000], 'bandpass', 8000)).toThrow();
  });
});

describe('spectrum', () => {
  const fs = 8000;
  const tone = generate({ waveform: 'sine', frequency: 1000, endFrequency: 0, amplitude: 0.5, duration: 1, sampleRate: fs });

  it('averaged spectrum peaks at the tone with its amplitude', () => {
    const { frequencies, amplitudes } = averagedSpectrum(tone, fs, 1024, 'hann');
    const peak = amplitudes.indexOf(Math.max(...amplitudes));
    expect(frequencies[peak]).toBe(1000); // 1000 Hz falls exactly on bin 128
    expect(amplitudes[peak]).toBeCloseTo(0.5, 3);
  });

  it('spectrogram is normalised to 0 dB and clamped at the dynamic range', () => {
    const s = spectrogram(tone, fs, 512, 128, 80);
    expect(s.frames).toBe(Math.floor((fs - 512) / 128) + 1);
    expect(Math.max(...s.db)).toBeCloseTo(0, 6);
    expect(Math.min(...s.db)).toBeGreaterThanOrEqual(-80);
    const firstFrame = Array.from(s.db.subarray(0, s.bins));
    expect(firstFrame.indexOf(Math.max(...firstFrame)) * s.binStep).toBe(1000);
  });
});

describe('wav', () => {
  it('round-trips 16-bit PCM', () => {
    const left = Float32Array.from([0, 0.5, -0.5, 1, -1, 0.25]);
    const right = Float32Array.from([0.1, -0.1, 0.2, -0.2, 0.3, -0.3]);
    const decoded = parseWav(encodeWav({ sampleRate: 22050, channels: [left, right] }));
    expect(decoded.sampleRate).toBe(22050);
    expect(decoded.channels).toHaveLength(2);
    expect(maxAbsDiff(decoded.channels[0], left)).toBeLessThan(1 / 32767);
    expect(maxAbsDiff(decoded.channels[1], right)).toBeLessThan(1 / 32767);
  });

  it('rejects non-WAV data', () => {
    expect(() => parseWav(new ArrayBuffer(64))).toThrow(/Not a WAV/);
  });
});
